helpers='''private:\n    using StartIter = std::map<std::int64_t, std::int64_t>::iterator;\n\n    void recordLifoSignal(int rankPermille) {\n        const bool nearNewest = rankPermille <= kLifoRankThresholdPermille;\n        recentRemovalRanks.push_back(nearNewest ? 1 : 0);\n        if (nearNewest) ++nearNewestRemovalCount;\n        if (recentRemovalRanks.size() > kLifoRankWindow) {\n            nearNewestRemovalCount -= static_cast<std::size_t>(recentRemovalRanks.front());\n            recentRemovalRanks.pop_front();\n        }\n        if (recentRemovalRanks.size() < kLifoMinObservations) return;\n        const std::size_t n = recentRemovalRanks.size();\n        if (!lifoTailMode &&\n            nearNewestRemovalCount * 100 >= n * static_cast<std::size_t>(kLifoEnablePercent)) {\n            lifoTailMode = true;\n            const StartIter tail = tailGap();\n            lifoArenaStart = tail == freeByStart.end() ? trenchLength : tail->first;\n        } else if (lifoTailMode &&\n                   nearNewestRemovalCount * 100 < n * static_cast<std::size_t>(kLifoDisablePercent)) {\n            lifoTailMode = false;\n        }\n    }\n\n    StartIter bestFittingGapInLifoArena(\n        int length, bool highSide, int sizeCohort) {\n        if (parityCohortMode) {\n            const auto& preferred = freeBySizeCohort[static_cast<std::size_t>(sizeCohort)];\n            StartIter gap = bestFittingArenaGapFromSet(preferred, length, highSide);\n            if (gap != freeByStart.end()) return gap;\n            return bestFittingArenaGapFromSet(freeBySizeShared, length, highSide);\n        }\n        return bestFittingArenaGapFromSet(freeBySize, length, highSide);\n    }\n\n    StartIter bestFittingArenaGapFromSet(\n        const std::set<std::pair<std::int64_t, std::int64_t>>& gaps,\n        int length, bool highSide) {\n        auto it = gaps.lower_bound({length, 0});\n        StartIter best = freeByStart.end();\n        std::int64_t bestScore = std::numeric_limits<std::int64_t>::max();\n        while (it != gaps.end()) {\n            const std::int64_t gapLength = it->first;\n            const std::int64_t slack = gapLength - length;\n            if (slack > 40) break;\n            if (it->second >= lifoArenaStart) {\n                std::int64_t score = slack * static_cast<std::int64_t>(recentLengths.size());\n                if (slack > 0) {\n                    int misses = 0;\n                    for (int request = static_cast<int>(slack) + 1; request <= 40; ++request) {\n                        misses += recentFrequency[static_cast<std::size_t>(request)];\n                    }\n                    score += kUnfitPenaltyScale * misses;\n                }\n                if (score < bestScore ||\n                    (score == bestScore && best != freeByStart.end() &&\n                     ((highSide && it->second > best->first) ||\n                      (!highSide && it->second < best->first)))) {\n                    bestScore = score;\n                    best = freeByStart.find(it->second);\n                }\n            }\n            const std::int64_t currentSize = it->first;\n            it = gaps.upper_bound({currentSize, std::numeric_limits<std::int64_t>::max()});\n        }\n        return best;\n    }\n\n    void commitPlacement(int length, int sizeCohort, std::int64_t start, std::int64_t digs) {\n        printPlacement(digs, start);\n        const int pid = static_cast<int>(pipes.size());\n        pipes.push_back(Pipe{start, length, true, sizeCohort});\n        fenwickAdd(pid, 1);\n        ++activePipeCount;\n        ++lengthOccurrenceCount[static_cast<std::size_t>(length)];\n        recordLength(length);\n        recordObservation(Observation{1, length});\n    }\n\n    void placeOnLifoTail(int length, int sizeCohort) {\n        StartIter tail = tailGap();\n        int tailCohort = parityCohortMode ? sizeCohort : -1;\n        const std::int64_t tailStart = tail == freeByStart.end()\n            ? trenchLength : tail->first;\n        if (tail != freeByStart.end()) tailCohort = gapCohort.at(tail->first);\n        const std::int64_t tailLength = trenchLength - tailStart;\n        const std::int64_t deficit = std::max<std::int64_t>(0, length - tailLength);\n        const std::int64_t digs = (deficit + kDigLength - 1) / kDigLength;\n        if (tail != freeByStart.end()) eraseGap(tail);\n        trenchLength += digs * kDigLength;\n        const std::int64_t remainderStart = tailStart + static_cast<std::int64_t>(length);\n        if (remainderStart < trenchLength) {\n            addFreeGap(remainderStart, trenchLength, tailCohort);\n        }\n        commitPlacement(length, sizeCohort, tailStart, digs);\n    }\n\n'''
